    ("B3EE xor 0xAA", bytes((b ^ 0xAA) & 0xff for b in B3EE)),
    ("B3EE xor 0xFF", bytes((b ^ 0xFF) & 0xff for b in B3EE)),
    ("B3EE not", bytes((~b) & 0xff for b in B3EE)),
    ("B3EE - 1", bytes((b - 1) & 0xff for b in B3EE)),
    ("B3EE + 1", bytes((b + 1) & 0xff for b in B3EE)),
